Here is the commit message:
libxl: fix coverity issues introduced by 6a95edf

As discussed here [0][1] Coverity reported two issues:

- On libxlDomainMigrationPrepareTunnel3 @@mig will be leaked on failures
after sucessfull call libxlDomainMigrationPrepareAny hence we free it.

Setting mig = NULL after @mig is assigned plus adding libxlMigrationCookieFree
on error paths addresses the issue. In case virThreadCreate fails,
unref of args frees the cookie on dispose function (libxlMigrationDstArgsDispose)

- On libxlMigrationStartTunnel @tc would be leaked.

Fixed by correctly saving the newly allocated @tc onto @tnl such that
libxlMigrationStopTunnel would free it up.

[0] https://www.redhat.com/archives/libvir-list/2017-February/msg00791.html
[1] https://www.redhat.com/archives/libvir-list/2017-February/msg00833.html

Signed-off-by: Joao Martins <joao.m.martins@oracle.com>

Here is the root cause:
The bug was caused by improper memory management in the migration functions, specifically where allocated resources (like the migration cookie and tunnel control structure) were not being freed in error paths, leading to memory leaks. The failure to set pointers to `NULL` after freeing them also contributed to potential use-after-free issues.

Here is the patch:

 int
 libxlDomainMigrationPrepareTunnel3(virConnectPtr dconn,
                                    virStreamPtr st,
                                    virDomainDefPtr *def,
                                    const char *cookiein,
                                    int cookieinlen,
                                    unsigned int flags)
 {
     libxlMigrationCookiePtr mig = NULL;
     libxlDriverPrivatePtr driver = dconn->privateData;
     virDomainObjPtr vm = NULL;
     libxlMigrationDstArgs *args = NULL;
     virThread thread;
     bool taint_hook = false;
     libxlDomainObjPrivatePtr priv = NULL;
     char *xmlout = NULL;
     int dataFD[2] = { -1, -1 };
     int ret = -1;

     if (libxlDomainMigrationPrepareAny(dconn, def, cookiein, cookieinlen,
                                        &mig, &xmlout, &taint_hook) < 0)
         goto error;

     if (!(vm = virDomainObjListAdd(driver->domains, *def,
                                    driver->xmlopt,
                                    VIR_DOMAIN_OBJ_LIST_ADD_LIVE |
                                    VIR_DOMAIN_OBJ_LIST_ADD_CHECK_LIVE,
                                    NULL)))
         goto error;

     *def = NULL;
     priv = vm->privateData;

     if (taint_hook) {
         /* Domain XML has been altered by a hook script. */
         priv->hookRun = true;
     }

     /*
      * The data flow of tunnel3 migration in the dest side:
      * stream -> pipe -> recvfd of libxlDomainStartRestore
      */
     if (pipe(dataFD) < 0)
         goto error;

     /* Stream data will be written to pipeIn */
     if (virFDStreamOpen(st, dataFD[1]) < 0)
         goto error;
     dataFD[1] = -1; /* 'st' owns the FD now & will close it */

     if (libxlMigrationDstArgsInitialize() < 0)
         goto error;

     if (!(args = virObjectNew(libxlMigrationDstArgsClass)))
         goto error;

     args->conn = dconn;
     args->vm = vm;
     args->flags = flags;
     args->migcookie = mig;
     /* Receive from pipeOut */
     args->recvfd = dataFD[0];
     args->nsocks = 0;
+    mig = NULL;
+
     if (virThreadCreate(&thread, false, libxlDoMigrateReceive, args) < 0) {
         virReportError(VIR_ERR_OPERATION_FAILED, "%s",
                        _("Failed to create thread for receiving migration data"));
         goto error;
     }

     ret = 0;
     goto done;

  error:
+    libxlMigrationCookieFree(mig);
     VIR_FORCE_CLOSE(dataFD[1]);
     VIR_FORCE_CLOSE(dataFD[0]);
     virObjectUnref(args);
     /* Remove virDomainObj from domain list */
     if (vm) {
         virDomainObjListRemove(driver->domains, vm);
         vm = NULL;
     }

  done:
     if (vm)
         virObjectUnlock(vm);

     return ret;
 }


 static int
 libxlMigrationStartTunnel(libxlDriverPrivatePtr driver,
                           virDomainObjPtr vm,
                           unsigned long flags,
                           virStreamPtr st,
-                          struct libxlTunnelControl *tc)
+                          struct libxlTunnelControl **tnl)
 {
+    struct libxlTunnelControl *tc = NULL;
     libxlTunnelMigrationThread *arg = NULL;
     int ret = -1;

     if (VIR_ALLOC(tc) < 0)
         goto out;
+    *tnl = tc;

     tc->dataFD[0] = -1;
     tc->dataFD[1] = -1;
     if (pipe(tc->dataFD) < 0) {
         virReportError(errno, "%s", _("Unable to make pipes"));
         goto out;
     }

     arg = &tc->tmThread;
     /* Read from pipe */
     arg->srcFD = tc->dataFD[0];
     /* Write to dest stream */
     arg->st = st;
     if (virThreadCreate(&tc->thread, true,
                         libxlTunnel3MigrationFunc, arg) < 0) {
         virReportError(errno, "%s",
                        _("Unable to create tunnel migration thread"));
         goto out;
     }

     virObjectUnlock(vm);
     /* Send data to pipe */
     ret = libxlDoMigrateSend(driver, vm, flags, tc->dataFD[1]);
     virObjectLock(vm);

  out:
     /* libxlMigrationStopTunnel will be called in libxlDoMigrateP2P to free
      * all resources for us. */
     return ret;
 }

  */
 static int
 libxlDoMigrateP2P(libxlDriverPrivatePtr driver,
                   virDomainObjPtr vm,
                   virConnectPtr sconn,
                   const char *xmlin,
                   virConnectPtr dconn,
                   const char *dconnuri ATTRIBUTE_UNUSED,
                   const char *dname,
                   const char *uri,
                   unsigned int flags)
 {
     virDomainPtr ddomain = NULL;
     virTypedParameterPtr params = NULL;
     int nparams = 0;
     int maxparams = 0;
     char *uri_out = NULL;
     char *dom_xml = NULL;
     unsigned long destflags;
     char *cookieout = NULL;
     int cookieoutlen;
     bool cancelled = true;
     virErrorPtr orig_err = NULL;
     int ret = -1;
     /* For tunnel migration */
     virStreamPtr st = NULL;
     struct libxlTunnelControl *tc = NULL;

     dom_xml = libxlDomainMigrationBegin(sconn, vm, xmlin,
                                         &cookieout, &cookieoutlen);
     if (!dom_xml)
         goto cleanup;

     if (virTypedParamsAddString(&params, &nparams, &maxparams,
                                 VIR_MIGRATE_PARAM_DEST_XML, dom_xml) < 0)
         goto cleanup;

     if (dname &&
         virTypedParamsAddString(&params, &nparams, &maxparams,
                                 VIR_MIGRATE_PARAM_DEST_NAME, dname) < 0)
         goto cleanup;

     if (uri &&
         virTypedParamsAddString(&params, &nparams, &maxparams,
                                 VIR_MIGRATE_PARAM_URI, uri) < 0)
         goto cleanup;

     /* We don't require the destination to have P2P support
      * as it looks to be normal migration from the receiver perpective.
      */
     destflags = flags & ~(VIR_MIGRATE_PEER2PEER);

     VIR_DEBUG("Prepare3");
     virObjectUnlock(vm);
     if (flags & VIR_MIGRATE_TUNNELLED) {
         if (!(st = virStreamNew(dconn, 0)))
             goto cleanup;
         ret = dconn->driver->domainMigratePrepareTunnel3Params
             (dconn, st, params, nparams, cookieout, cookieoutlen, NULL, NULL, destflags);
     } else {
         ret = dconn->driver->domainMigratePrepare3Params
             (dconn, params, nparams, cookieout, cookieoutlen, NULL, NULL, &uri_out, destflags);
     }
     virObjectLock(vm);

     if (ret == -1)
         goto cleanup;

     if (!(flags & VIR_MIGRATE_TUNNELLED)) {
         if (uri_out) {
             if (virTypedParamsReplaceString(&params, &nparams,
                                             VIR_MIGRATE_PARAM_URI, uri_out) < 0) {
                 orig_err = virSaveLastError();
                 goto finish;
             }
         } else {
             virReportError(VIR_ERR_INTERNAL_ERROR, "%s",
                            _("domainMigratePrepare3 did not set uri"));
             goto finish;
         }
     }

     VIR_DEBUG("Perform3 uri=%s", NULLSTR(uri_out));
     if (flags & VIR_MIGRATE_TUNNELLED)
-        ret = libxlMigrationStartTunnel(driver, vm, flags, st, tc);
+        ret = libxlMigrationStartTunnel(driver, vm, flags, st, &tc);
     else
         ret = libxlDomainMigrationPerform(driver, vm, NULL, NULL,
                                           uri_out, NULL, flags);
     if (ret < 0)
         orig_err = virSaveLastError();

     cancelled = (ret < 0);

  finish:
     VIR_DEBUG("Finish3 ret=%d", ret);
     if (virTypedParamsGetString(params, nparams,
                                 VIR_MIGRATE_PARAM_DEST_NAME, NULL) <= 0 &&
         virTypedParamsReplaceString(&params, &nparams,
                                     VIR_MIGRATE_PARAM_DEST_NAME,
                                     vm->def->name) < 0) {
         ddomain = NULL;
     } else {
         virObjectUnlock(vm);
         ddomain = dconn->driver->domainMigrateFinish3Params
             (dconn, params, nparams, NULL, 0, NULL, NULL,
              destflags, cancelled);
         virObjectLock(vm);
     }

     cancelled = (ddomain == NULL);

     /* If Finish3Params set an error, and we don't have an earlier
      * one we need to preserve it in case confirm3 overwrites
      */
     if (!orig_err)
         orig_err = virSaveLastError();

     VIR_DEBUG("Confirm3 cancelled=%d vm=%p", cancelled, vm);
     ret = libxlDomainMigrationConfirm(driver, vm, flags, cancelled);

     if (ret < 0)
         VIR_WARN("Guest %s probably left in 'paused' state on source",
                  vm->def->name);

  cleanup:
     if (flags & VIR_MIGRATE_TUNNELLED) {
         libxlMigrationStopTunnel(tc);
         virObjectUnref(st);
     }

     if (ddomain) {
         virObjectUnref(ddomain);
         ret = 0;
     } else {
         ret = -1;
     }

     if (orig_err) {
         virSetError(orig_err);
         virFreeError(orig_err);
     }

     VIR_FREE(cookieout);
     VIR_FREE(dom_xml);
     VIR_FREE(uri_out);
     virTypedParamsFree(params, nparams);
     return ret;
 }



